function decimalClose(actual, text) {
  const expected = Number(text);
  expect(Number.isFinite(actual)).toBe(true);
  if (expected === 0) expect(actual).toBe(0);
  else {
    expect(actual).toBeGreaterThan(0);
    expect(Math.abs(actual - expected) / expected).toBeLessThan(5e-13);
  }
}

describe('Cit/Cr — independent Decimal90 production regression', () => {
  it.each(DECIMAL_GOLDENS)('%s', (_name, patch, expected) => {
    const input = { ...example, ...patch };
    const result = engine.evaluate(input, policy);
    expect(result.valid).toBe(expected.valid);
    if (!expected.valid) {
      expect(result.snapshot).toBeNull(); expect(result.rawValue).toBeNull();
      return;
    }
    decimalClose(result.rawValue, expected.raw);
    if (expected.native === null) expect(result.nativeSI).toBeNull();
    else decimalClose(result.nativeSI, expected.native);
    expect(result).toMatchObject({ status: expected.status, unit: expected.unit, originalUnit: expected.originalUnit, basis: expected.basis, comparator: expected.comparator });
    expect(result.category).toBe(expected.status === 'unassessed' ? null : expected.status);
    expect(result.tone).toBe(expected.status === 'within' ? 'success' : ['below', 'above'].includes(expected.status) ? 'warning' : 'neutral');
    expect(Number(result.display.value)).toBeGreaterThanOrEqual(0);
    if (Number(expected.raw) > 0) expect(Number(result.display.value)).toBeGreaterThan(0);
    if (expected.reference === null) expect(result.reference).toBeNull();
    else {
      expect(result.reference).toMatchObject({ nativeLow: Number(expected.reference.lower), nativeHigh: expected.reference.upper === null ? null : Number(expected.reference.upper), lowerInclusive: expected.reference.lowerInclusive });
      expect(result.source.id).toBe(expected.reference.source);
      const shown = [result.reference.display.lower, result.reference.display.upper].filter(v => v !== null).map(v => Number(v.replace(',', '.')));
      expect(shown).toEqual(expected.reference.displayValues.map(Number));
      if (expected.reference.kind === 'lower') expect(result.reference.range).toMatch(/^>/);
    }
    if (expected.boundaryRequired) expect(result.boundary).toContain('przed zaokrągleniem');
    expect(result.snapshot).toMatchObject({ schema: 'clcr-citcr', version: 1, rawValue: result.rawValue, context: { ageYears: input.ageYears, sex: input.sex } });
    if (input.mode === 'direct') expect(result.snapshot.input.reportedValue).toBe(input.reportedValue);
    else expect(result.snapshot.input).toMatchObject({ citrateValue: input.citrateValue, citrateUnit: input.citrateUnit, creatinineValue: input.creatinineValue, creatinineUnit: input.creatinineUnit });
  });
});

describe('Cit/Cr — policy injection, source metadata and one norm formatter', () => {
  it('keeps the two source profiles separate, source-native units and strict child lower limits', () => {
    expect(data.getPolicy(policy.id)).toBe(policy);
    expect(data.getPolicy('missing')).toBeNull(); expect(data.getProfile('missing')).toBeNull();
    expect(data.listProfiles()).toEqual(policy.profiles);
    const [child, adult] = policy.profiles;
    expect(child).toMatchObject({ id: 'PATHWEST_CITCR_SPOT_2025', referenceKind: 'lower-reference-limit', population: { sexSpecific: false }, source: { fullDocumentRead: true, date: '2025-08-13', method: 'Nie podano w katalogu' } });
    expect(child.bands.map(b => [b.minimumAgeMonths, b.maximumAgeMonths, b.lower, b.upper, b.lowerInclusive])).toEqual([[0, 36, 300, null, false], [36, 216, 100, null, false]]);
    expect(adult.bands.map(b => [b.minimumAgeMonths, b.sex, b.lower, b.upper, b.lowerInclusive, b.upperInclusive])).toEqual([[216, 'M', 40, 330, true, true], [216, 'F', 110, 550, true, true]]);
    expect(adult.restrictions.ageSelectionPolicy).toContain('polityką aplikacji');
    expect(adult.restrictions.endpointPolicy).toContain('konwencją aplikacji');
    expect(Object.isFrozen(child.source)).toBe(true);
    expect(policy.notes.lowResultSource).toContain('10.1007/s00467-008-1073-x');
  });

  it('does not silently use default norms if the policy is absent or malformed', () => {
    expect(engine.evaluate(example)).toMatchObject({ valid: true, rawValue: 0.1, reasonCode: 'missing-profile', reference: null, source: null, category: null, tone: 'neutral' });
    for (const invalid of [
      { ...policy, quantity: 'calcium' }, { ...policy, profiles: [] }, { ...policy, notes: null },
      { ...policy, conversionConstants: { ...policy.conversionConstants, citricAcidMgPerMmol: '-192' } },
      { ...policy, profiles: [{ ...policy.profiles[0], bands: [{ ...policy.profiles[0].bands[0], lowerInclusive: null }] }] },
      { ...policy, profiles: [{ ...policy.profiles[0], bands: [{ ...policy.profiles[0].bands[0], upper: 999 }] }] },
    ]) expect(calculate({}, invalid)).toMatchObject({ valid: true, rawValue: 0.1, reasonCode: 'invalid-profile', category: null, reference: null });
  });

  it('accepts an injected population without mutating it or choosing the most favorable source', () => {
    const synthetic = structuredClone(policy);
    synthetic.id = 'SYNTHETIC_CITCR'; synthetic.profiles[0].id = 'SYNTHETIC_CHILD';
    synthetic.profiles[0].population.label = 'Fikcyjna populacja'; synthetic.profiles[0].bands[1].lower = 50;
    const before = structuredClone(synthetic);
    expect(calculate({}, synthetic)).toMatchObject({ category: 'within', profileId: 'SYNTHETIC_CHILD', population: { label: 'Fikcyjna populacja' }, reference: { nativeLow: 50 } });
    expect(synthetic).toEqual(before); expect(Object.isFrozen(synthetic)).toBe(false);
    expect(calculate().category).toBe('below');
    synthetic.profiles[0].bands = [];
    expect(calculate({}, synthetic).reasonCode).toBe('invalid-profile');
    const overlapping = structuredClone(policy);
    overlapping.profiles[0].bands.push(structuredClone(overlapping.profiles[0].bands[1]));
    expect(calculate({}, overlapping)).toMatchObject({ reasonCode: 'ambiguous-age-band', reference: null, category: null });
  });

  it.each(['umol/mmol', 'mmol/mol', 'mmol/mmol', 'mol/mol', 'mg/mg:acid', 'mg/g:acid', 'mg/mmol:acid', 'mg/mg:ion', 'mg/g:ion', 'mg/mmol:ion'])('uses the same norm formatter in the main reference and all rows for %s', unit => {
    const result = reported('0.1', unit);
    expect(result.referenceTable).toHaveLength(4);
    expect(result.referenceTable.filter(r => r.selected)).toHaveLength(1);
    for (const row of result.referenceTable) {
      const band = policy.profiles.find(profile => profile.id === row.profileId).bands.find(band => band.id === row.id);
      const formatted = engine.formatReference(band, unit, policy.conversionConstants);
      expect(row.display).toEqual(formatted.display);
      expect(row.range).toBe(formatted.range); expect(row.unit).toBe(result.unit);
      expect(row.nativeUnit).toBe('µmol/mmol');
      expect(row.sourceOriginal.unit).toBe('mmol/mmol');
    }
    const selected = result.referenceTable.find(r => r.selected);
    expect(selected.display).toEqual(result.reference.display);
    expect(selected.range).toBe(result.reference.range);
    expect(result.sourceReferenceTable.map(r => [r.range, r.unit])).toEqual([
      ['>0,3', 'mmol/mmol'], ['>0,1', 'mmol/mmol'], ['0,04–0,33', 'mmol/mmol'], ['0,11–0,55', 'mmol/mmol'],
    ]);
  });

  it('does not pretend that unknown mass basis has converted norm rows', () => {
    const result = reported('0.1', 'mg/mg:unknown');
    expect(result.referenceTable).toEqual([]); expect(result.sourceReferenceTable).toHaveLength(4);
    expect(result.sourceReferenceTable.every(row => row.selected === false)).toBe(true);
    expect(engine.formatReference(policy.profiles[0].bands[1], 'mg/mg:unknown')).toBeNull();
    expect(engine.formatReference(null, 'umol/mmol')).toBeNull();
    expect(engine.formatReference(policy.profiles[0].bands[1], 'mg/mg:acid', {})).toBeNull();
  });

  it('retains exact rational values even on different sides of a boundary rounded to the same Number', () => {
    const above = reported('100.0000000000000000001'), below = reported('99.9999999999999999999');
    expect(above.nativeSI).toBe(100); expect(below.nativeSI).toBe(100);
    expect(above.category).toBe('within'); expect(below.category).toBe('below');
    expect(above.exactNativeSI).toEqual({ numerator: '1000000000000000000001', denominator: '10000000000000000000' });
    expect(below.exactNativeSI).toEqual({ numerator: '999999999999999999999', denominator: '10000000000000000000' });
    expect(above.snapshot.exactNativeSI).toEqual(above.exactNativeSI);
  });

  it('treats explicit current prematurity separately from a distant history and preserves known facts', () => {
    const knownFacts = { historyOfPrematurity: true, infection: false, hematuria: null };
    expect(calculate({ knownFacts, population: { currentPreterm: false } })).toMatchObject({ referenceAvailable: true, context: { knownFacts, population: { currentPreterm: false } } });
    const distant = calculate({ knownFacts, population: undefined });
    expect(distant).toMatchObject({ referenceAvailable: true, context: { knownFacts } });
    expect(distant.context.population).toEqual({});
    expect(calculate({ population: undefined, currentPreterm: true })).toMatchObject({ valid: true, referenceAvailable: false, reasonCode: 'unsupported-population', context: { population: { currentPreterm: true } } });
    const synthetic = structuredClone(policy); synthetic.restrictions.restrictedSampleTypes = [];
    expect(calculate({ sampleType: 'timed' }, synthetic).referenceAvailable).toBe(true);
    expect(calculate({ sampleType: 'timed' }).reasonCode).toBe('unsupported-sample-type');
  });

  it('has the accepted two-sentence low comment without pretending to diagnose a cause', () => {
    const note = 'Obniżony Cit/Cr może wskazywać na słabszą ochronę przed kamicą wapniową. Bywa związany m.in. z kwasicą metaboliczną lub hipokaliemią; sam wynik nie ustala przyczyny.';
    expect(calculate().qualification.note).toBe(note);
    expect(reported('0', 'umol/mmol', { ageYears: 40, sex: 'F' }).qualification.note).toBe(note);
  });

  it('does not impose arbitrary raw-unit maxima and freezes an independent versioned snapshot', () => {
    for (const [creatinineUnit, creatinineValue] of [['mg/dL', '678.72'], ['mmol/L', '60'], ['umol/L', '60000']]) {
      expect(calculate({ citrateValue: '6', citrateUnit: 'umol/L', creatinineValue, creatinineUnit })).toMatchObject({ valid: true, rawValue: 0.1, category: 'below' });
    }
    const result = calculate({ ageYears: 18, sex: 'M' });
    expect(result.snapshot).toMatchObject({ schema: 'clcr-citcr', version: 1, policyId: policy.id, policyVersion: 1, profileId: 'NEWCASTLE_CITCR_RANDOM_2025', profileVersion: 1, context: { ageYears: 18, sex: 'M' }, conversion: { constants: { citrateIonMgPerMmol: '189.099', citricAcidMgPerMmol: '192.1235', creatinineMgPerMmol: '113.12' } } });
    expect(Object.isFrozen(result.snapshot.input)).toBe(true);
    expect(result.snapshot.reference).not.toBe(result.reference);
    expect(result.snapshot).not.toHaveProperty('snapshot');
  });
});

describe('Cit/Cr — production DOM reader and legacy compatibility', () => {
  function documentWith(patch = {}) {
    const values = { formulaPicker: 'CitCr_spot', age: '8', ageMonths: '0', ageDays: '12', sex: 'F', CitCr_entry_mode: 'concentration', Cit_Cr_spot: '10', Cit_Cr_spot_unit: 'mg/dL', citrateSpotReportingEntity: 'acid', Ucr_spot: '100', Ucr_spot_unit: 'mg/dL', CitCr_reported: '0.1', CitCr_reported_unit: 'mg/mg', CitCr_reported_basis: 'ion', CitCr_same_specimen: '', ...patch };
    const controls = Object.fromEntries(Object.entries(values).map(([key, value]) => [key, typeof value === 'boolean' ? { checked: value } : { value }]));
    return { controls, getElementById: id => controls[id], defaultView: browser };
  }
  it('composes separate unit and mass-basis controls and reuses age and sex', () => {
    const input = engine.readInputFromDocument(documentWith());
    expect(input).toMatchObject({ mode: 'concentration', citrateUnit: 'mg/dL:acid', reportedUnit: 'mg/mg:ion', ageYears: 8, sex: 'F', sameSpecimen: 'assumed' });
    expect(engine.evaluate(input, policy)).toMatchObject({ valid: true, rawValue: 0.1, category: 'below' });
    const molar = engine.readInputFromDocument(documentWith({ Cit_Cr_spot_unit: 'umol/L', CitCr_reported_unit: 'mmol/mmol' }));
    expect(molar.citrateUnit).toBe('umol/L'); expect(molar.reportedUnit).toBe('mmol/mmol');
  });
  it('retains the explicitly labelled acid legacy fallback only when the selector is absent', () => {
    const doc = documentWith(); delete doc.controls.Cit_Cr_spot_unit; delete doc.controls.citrateSpotReportingEntity;
    expect(engine.readInputFromDocument(doc).citrateUnit).toBe('mg/dL:acid');
    doc.controls.Cit_Cr_spot_unit = { value: '' };
    expect(engine.readInputFromDocument(doc).citrateUnit).toBe('');
    doc.controls.Cit_Cr_spot_unit.value = 'mg/dL';
    expect(engine.readInputFromDocument(doc).citrateUnit).toBe('mg/dL:unknown');
    expect(engine.evaluate(engine.readInputFromDocument(doc), policy)).toMatchObject({ valid: true, rawValue: 0.1, reasonCode: 'unknown-mass-basis' });
  });
  it('does not require months/days in the one birth-to-under3 band or consume stale ageDays', () => {
    for (const age of ['0', '1', '2']) {
      const doc = documentWith({ age, ageMonths: '', ageDays: '-10' });
      expect(engine.readInputFromDocument(doc).ageYears).toBe(Number(age));
      expect(engine.evaluate(engine.readInputFromDocument(doc), policy).reference.nativeLow).toBe(300);
      expect(doc.controls.ageMonths.value).toBe(''); expect(doc.controls.ageDays.value).toBe('-10');
    }
    expect(engine.readInputFromDocument(documentWith({ age: '3', ageMonths: '' })).ageYears).toBe(3);
    expect(engine.readInputFromDocument(documentWith({ age: '2', ageMonths: '12' })).ageYears).toBeNull();
    expect(engine.readInputFromDocument(documentWith({ age: '', ageMonths: '' })).ageYears).toBeNull();
  });
  it('does not turn remote prematurity or newborn fields into a current preterm exclusion', () => {
    const doc = documentWith({ neonatalTermStatus: 'preterm', neonatalGestationalAgeWeeks: '30' });
    const input = engine.readInputFromDocument(doc);
    expect(input).not.toHaveProperty('population');
    expect(engine.evaluate(input, policy).referenceAvailable).toBe(true);
    const current = engine.readInputFromDocument(doc, { population: { currentPreterm: true } });
    expect(engine.evaluate(current, policy).reasonCode).toBe('unsupported-population');
  });
  it('gives explicit no/unknown precedence over old checkbox booleans and preserves three-state facts', () => {
    const doc = documentWith({ spotSameSpecimen: true, ui_spotSameSpecimen_answer: 'no', spotInfection: true, ui_spotInfection_answer: 'no', spotHematuria: true, ui_spotHematuria_answer: 'unknown', spotExercise: true });
    const input = engine.readInputFromDocument(doc);
    expect(input).toMatchObject({ sameSpecimen: 'different', knownFacts: { infection: false, hematuria: null, exercise: true }, confounders: ['exercise'] });
    expect(engine.evaluate(input, policy).reasonCode).toBe('different-specimens');
    doc.controls.CitCr_entry_mode.value = 'direct';
    expect(engine.evaluate(engine.readInputFromDocument(doc), policy)).toMatchObject({ valid: true, context: { sameSpecimen: 'not-applicable' } });
    expect(engine.readInputFromDocument(doc, { concentrationOnly: true }).mode).toBe('concentration');
    doc.controls.ui_spotSameSpecimen_answer.value = 'unknown';
    expect(engine.readInputFromDocument(doc).sameSpecimen).toBe('assumed');
  });
});
